+	defer db.Close()
+	
+	// Insert items that should create overflow buckets
+	// We'll use keys that hash to the same bucket
+	for i := 0; i < 50; i++ {
+		key := fmt.Sprintf("key%05d", i)
+		value := fmt.Sprintf("value%05d", i)
+		err := db.Put([]byte(key), []byte(value))
