+package main
+
+import (
+	"fmt"
+	"os"
+	"github.com/akrylysov/pogreb"
+)
+
+func main() {
+	// Clean up any existing test database
+	os.RemoveAll("simple_test.db")
+	
+	// Open database
+	db, err := pogreb.Open("simple_test.db", nil)
+	if err != nil {
+		panic(err)
+	}
+	defer db.Close()
+	
+	// Insert items that should create overflow buckets
+	// We'll use keys that hash to the same bucket
+	for i := 0; i < 50; i++ {
+		key := fmt.Sprintf("key%05d", i)
+		value := fmt.Sprintf("value%05d", i)
+		err := db.Put([]byte(key), []byte(value))
+		if err != nil {
+			panic(err)
+		}
+	}
+	
+	fmt.Printf("Inserted %d items\n", 50)
+	
+	// Verify items exist
+	for i := 0; i < 10; i++ {
+		key := fmt.Sprintf("key%05d", i)
+		val, err := db.Get([]byte(key))
+		if err != nil {
+			panic(err)
+		}
+		if val == nil {
+			fmt.Printf("Key %s not found!\n", key)
+		} else {
+			fmt.Printf("Key %s found with value %s\n", key, string(val))
+		}
+	}
+	
+	// Delete some items
+	for i := 0; i < 25; i++ {
+		key := fmt.Sprintf("key%05d", i)
+		err := db.Delete([]byte(key))
+		if err != nil {
+			panic(err)
+		}
+	}
+	
+	fmt.Printf("Deleted %d items\n", 25)
+	
+	// Verify remaining items still exist
+	for i := 25; i < 35; i++ {
+		key := fmt.Sprintf("key%05d", i)
+		val, err := db.Get([]byte(key))
+		if err != nil {
+			panic(err)
+		}
+		if val == nil {
+			fmt.Printf("Key %s not found!\n", key)
+		} else {
+			fmt.Printf("Key %s found with value %s\n", key, string(val))
+		}
+	}
+	
+	fmt.Println("Simple test completed successfully!")
+}
