@@ -0,0 +1,49 @@
+func (idx *index) delete(hash uint32, matchKey matchKeyFunc) error {
+	var prevBucket *bucketHandle
+	it := idx.newBucketIterator(idx.bucketIndex(hash))
+	for {
+		b, err := it.next()
+		if err == ErrIterationDone {
+			return nil
+		}
+		if err != nil {
+			return err
+		}
+		for i := 0; i < slotsPerBucket; i++ {
+			sl := b.slots[i]
+			if sl.offset == 0 {
+				break
+			}
+			if hash != sl.hash {
+				continue
+			}
+			match, err := matchKey(sl)
+			if err != nil {
+				return err
+			}
+			if !match {
+				continue
+			}
+			b.del(i)
+			if err := b.write(); err != nil {
+				return err
+			}
+			// Check if the current bucket is empty after deletion
+			// Only free overflow buckets (identified by prevBucket != nil)
+			if b.isEmpty() && prevBucket != nil {
+				// This is an empty overflow bucket, free it
+				emptyBucketOffset := b.offset
+				// Update previous bucket to skip this bucket
+				prevBucket.next = b.next
+				if err := prevBucket.write(); err != nil {
+					return err
+				}
+				// Free the empty bucket
+				idx.freeOverflowBucket(emptyBucketOffset)
+			}
+			idx.numKeys--
+			return nil
+		}
+		prevBucket = &b
+	}
+}
